    "coordinates": [
      54.67495,
      25.28813
    ],
    "description": {
      "by": "Адрас: Aušros vartai, 7a.\n\nНа пачатку 19 ст. першы паверх паўднёвага корпуса базыльянскага кляштара быў перароблены ў турму, вязнямі якой у 1823-24 гг. былі арыштаваныя па справе філаматаў Адам Міцкевіч, Ігнат Дамейка і інш. Келля, дзе быў зняволены Міцкевіч, атрымала імя Конрада, бо менавіта тут разгортваліся падзеі ІІІ часткі паэмы “Дзяды”. На меркаваным месцы келлі ўсталяваная мемарыяльная шыльда Адаму Міцкевічу. \n\nУ частцы будынка, дзе месцілася келля Конрада, цяпер уладкаваны гатэль.",
      "ru": "Адрас: Aušros vartai, 7a.\n\nНа пачатку 19 ст. першы паверх паўднёвага корпуса базыльянскага кляштара быў перароблены ў турму, вязнямі якой у 1823-24 гг. былі арыштаваныя па справе філаматаў Адам Міцкевіч, Ігнат Дамейка і інш. Келля, дзе быў зняволены Міцкевіч, атрымала імя Конрада, бо менавіта тут разгортваліся падзеі ІІІ часткі паэмы “Дзяды”. На меркаваным месцы келлі ўсталяваная мемарыяльная шыльда Адаму Міцкевічу. \n\nУ частцы будынка, дзе месцілася келля Конрада, цяпер уладкаваны гатэль.",
      "en": "Адрас: Aušros vartai, 7a.\n\nНа пачатку 19 ст. першы паверх паўднёвага корпуса базыльянскага кляштара быў перароблены ў турму, вязнямі якой у 1823-24 гг. былі арыштаваныя па справе філаматаў Адам Міцкевіч, Ігнат Дамейка і інш. Келля, дзе быў зняволены Міцкевіч, атрымала імя Конрада, бо менавіта тут разгортваліся падзеі ІІІ часткі паэмы “Дзяды”. На меркаваным месцы келлі ўсталяваная мемарыяльная шыльда Адаму Міцкевічу. \n\nУ частцы будынка, дзе месцілася келля Конрада, цяпер уладкаваны гатэль."
    },
