      "en": "Адрас: Didžioji, 34.\n\nПабудаваны (1596-1618) паводле праекта мінскага архітэктара Яна Франкевіча. У першай палове 17 ст. тут адпраўляў службы, чытаў пропаведзі і спавядаў адзін з найбольш паважаных у беларускіх каталікоў святых Андрэй Баболя."
