    "id": "vilnia-bibliyateka-vedy-1908-11",
    "title": {
      "by": "Бібліятэка \"Веды\" (1908-11)",
      "ru": "Бібліятэка \"Веды\" (1908-11)",
      "en": "Бібліятэка \"Веды\" (1908-11)"
    },
    "category": "culture",
    "country": {
      "by": "Літва",
      "ru": "Литва",
      "en": "Lithuania"
    },
    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.68617,
      25.28486
    ],
    "description": {
      "by": "Адрас: Gedimino, 2.\n\nЗ 1908 па 1911 год пры віленскай бібліятэцы-чытальні \"Веды\"  месцілася беларускае выдавецкае таварыства \"Наша хата\". \n\nУладальнікам \"Ведаў\", як і заснавальнікам \"Нашай хаты\", быў беларускі мецэнат Барыс Даніловіч. У бібліятэцы нейкі час па пераездзе ў Вільню ў 1908 г. зарабляў на пражыццё Янка Купала.\n\nПадчас нацыстоўскай акупацыі тут працаваў Беларускі нацыянальны камітэт на чале з адраджэнцам Вацлавам Іваноўскім і месцілася рэдакцыя газеты \"Bielaruski holas\", якую рэдагаваў Францішак Аляхновіч.",
      "ru": "Адрас: Gedimino, 2.\n\nЗ 1908 па 1911 год пры віленскай бібліятэцы-чытальні \"Веды\"  месцілася беларускае выдавецкае таварыства \"Наша хата\". \n\nУладальнікам \"Ведаў\", як і заснавальнікам \"Нашай хаты\", быў беларускі мецэнат Барыс Даніловіч. У бібліятэцы нейкі час па пераездзе ў Вільню ў 1908 г. зарабляў на пражыццё Янка Купала.\n\nПадчас нацыстоўскай акупацыі тут працаваў Беларускі нацыянальны камітэт на чале з адраджэнцам Вацлавам Іваноўскім і месцілася рэдакцыя газеты \"Bielaruski holas\", якую рэдагаваў Францішак Аляхновіч.",
      "en": "Адрас: Gedimino, 2.\n\nЗ 1908 па 1911 год пры віленскай бібліятэцы-чытальні \"Веды\"  месцілася беларускае выдавецкае таварыства \"Наша хата\". \n\nУладальнікам \"Ведаў\", як і заснавальнікам \"Нашай хаты\", быў беларускі мецэнат Барыс Даніловіч. У бібліятэцы нейкі час па пераездзе ў Вільню ў 1908 г. зарабляў на пражыццё Янка Купала.\n\nПадчас нацыстоўскай акупацыі тут працаваў Беларускі нацыянальны камітэт на чале з адраджэнцам Вацлавам Іваноўскім і месцілася рэдакцыя газеты \"Bielaruski holas\", якую рэдагаваў Францішак Аляхновіч."
    },
