    "id": "vilnia-palats-slushki",
    "title": {
      "by": "Палац Слушкі",
      "ru": "Палац Слушкі",
      "en": "Палац Слушкі"
    },
    "category": "historical",
    "country": {
      "by": "Літва",
      "ru": "Литва",
      "en": "Lithuania"
    },
    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.6904,
      25.29738
    ],
    "description": {
      "by": "Адрас: Kosciuškos, 10.\n\nУ 1700 годзе на левым беразе ракі Вяллі, што на Антоклі, расчыніў дзверы пекны барочны палац. Ягоны падмурак полацкі ваявода Дамінік Слушка (1684?-13) загадаў паставіць на паўвыспе, адмыслова створанай на рацэ. Архітэктарам палаца быў адзін з лепшых віленскіх майстраў таго часу — італьянец П’етра Перці. Потым палац належаў Пузыням і Патоцкім, манахам-піярам (з 1756) і аўтару неўміручага паланезу “Развітанне з радзімай” Міхалу Клеафасу Агінскаму (з 1766).",
      "ru": "Адрас: Kosciuškos, 10.\n\nУ 1700 годзе на левым беразе ракі Вяллі, што на Антоклі, расчыніў дзверы пекны барочны палац. Ягоны падмурак полацкі ваявода Дамінік Слушка (1684?-13) загадаў паставіць на паўвыспе, адмыслова створанай на рацэ. Архітэктарам палаца быў адзін з лепшых віленскіх майстраў таго часу — італьянец П’етра Перці. Потым палац належаў Пузыням і Патоцкім, манахам-піярам (з 1756) і аўтару неўміручага паланезу “Развітанне з радзімай” Міхалу Клеафасу Агінскаму (з 1766).",
      "en": "Адрас: Kosciuškos, 10.\n\nУ 1700 годзе на левым беразе ракі Вяллі, што на Антоклі, расчыніў дзверы пекны барочны палац. Ягоны падмурак полацкі ваявода Дамінік Слушка (1684?-13) загадаў паставіць на паўвыспе, адмыслова створанай на рацэ. Архітэктарам палаца быў адзін з лепшых віленскіх майстраў таго часу — італьянец П’етра Перці. Потым палац належаў Пузыням і Патоцкім, манахам-піярам (з 1756) і аўтару неўміручага паланезу “Развітанне з радзімай” Міхалу Клеафасу Агінскаму (з 1766)."
    },
