      "en": "Адрас: Lukiškių aikštė.\n\nДраўляны крыж з мемарыяльнай плітой ў гонар лідараў антырасейскага паўстання 1863-64 гг. Кастуся Каліноўскага і Зігмунта Серакоўскага стаіць у глыбіні Лукішчкага пляцу, паблізу ад касцёла Святых Якуба і Піліпа."
