      "by": "Адрас: Pilies, 24.\n\nУ гэтым доме, дзе ўсталявана мемарыяльная дошка, з 1832 па 1835 гг. жыў славуты пісьменнік, гісторык і фалькларыст Юзэф Ігнацы Крашэўскі. Удзельнік паўстання 1830–31 гг., напісаў 223 (!) раманы пра гісторыю ВКЛ. Ягоныя бацькі паходзілі з Пружаншчыны, дзе мелі родавую сядзібу ў Доўгім.",
