    "id": "vilnia-palats-radzivilaw-sapehaw-patsaw",
    "title": {
      "by": "Палац Радзівілаў, Сапегаў, Пацаў",
      "ru": "Палац Радзівілаў, Сапегаў, Пацаў",
      "en": "Палац Радзівілаў, Сапегаў, Пацаў"
    },
    "category": "historical",
