    "id": "vilnia-kastsyol-svyatoha-mikhala",
    "title": {
      "by": "Касцёл Святога Міхала",
      "ru": "Касцёл Святога Міхала",
      "en": "Касцёл Святога Міхала"
    },
    "category": "grave",
    "country": {
      "by": "Літва",
      "ru": "Литва",
      "en": "Lithuania"
    },
    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.68293,
      25.29177
    ],
    "description": {
      "by": "Адрас: Šv. Mykolo, 9.\n\nПабудаваны ў 1625 г. пры кляштары бернардынак, пад які канцлер ВКЛ Леў Сапега аддаў свой палац. Будаўніцтва касцёла таксама цалкам фундаваў аўтар легендарнага “Трэцяга Статута ВКЛ”.\n\nПадчас Другой сусветнай вайны тут служыў пробашчам ідэалог беларускага Касцёла ксёндз Адам Станкевіч. З дазволу святара перад адыходам немцаў супрацоўнікі Беларускага Музэю ім. Івана Луцкевіча схавалі ў сутарэннях касцёла самыя каштоўныя экспанаты. З прыходам савецкай ўлады музейныя скарбы падзелілі Літоўская і Беларуская ССР. \n\nУ святых сценах Святога Міхала размясціўся Архітэктурны музей (1968-93). Увосень 2009 у касцёле расчыніў дзверы Музей царкоўнай спадчыны. \n\nНадмагільны помнік фундатару Льву Сапегу і двум ягоным жонкам месціцца справа ад галоўнага алтара. Таксама ў касцёле ёсць помнікі сыну і канцлера ВКЛ і іншым прадстаўнікам дынастыі. Прах Сапегаў спачывае ў крыпце пад алтаром.",
      "ru": "Адрас: Šv. Mykolo, 9.\n\nПабудаваны ў 1625 г. пры кляштары бернардынак, пад які канцлер ВКЛ Леў Сапега аддаў свой палац. Будаўніцтва касцёла таксама цалкам фундаваў аўтар легендарнага “Трэцяга Статута ВКЛ”.\n\nПадчас Другой сусветнай вайны тут служыў пробашчам ідэалог беларускага Касцёла ксёндз Адам Станкевіч. З дазволу святара перад адыходам немцаў супрацоўнікі Беларускага Музэю ім. Івана Луцкевіча схавалі ў сутарэннях касцёла самыя каштоўныя экспанаты. З прыходам савецкай ўлады музейныя скарбы падзелілі Літоўская і Беларуская ССР. \n\nУ святых сценах Святога Міхала размясціўся Архітэктурны музей (1968-93). Увосень 2009 у касцёле расчыніў дзверы Музей царкоўнай спадчыны. \n\nНадмагільны помнік фундатару Льву Сапегу і двум ягоным жонкам месціцца справа ад галоўнага алтара. Таксама ў касцёле ёсць помнікі сыну і канцлера ВКЛ і іншым прадстаўнікам дынастыі. Прах Сапегаў спачывае ў крыпце пад алтаром.",
      "en": "Адрас: Šv. Mykolo, 9.\n\nПабудаваны ў 1625 г. пры кляштары бернардынак, пад які канцлер ВКЛ Леў Сапега аддаў свой палац. Будаўніцтва касцёла таксама цалкам фундаваў аўтар легендарнага “Трэцяга Статута ВКЛ”.\n\nПадчас Другой сусветнай вайны тут служыў пробашчам ідэалог беларускага Касцёла ксёндз Адам Станкевіч. З дазволу святара перад адыходам немцаў супрацоўнікі Беларускага Музэю ім. Івана Луцкевіча схавалі ў сутарэннях касцёла самыя каштоўныя экспанаты. З прыходам савецкай ўлады музейныя скарбы падзелілі Літоўская і Беларуская ССР. \n\nУ святых сценах Святога Міхала размясціўся Архітэктурны музей (1968-93). Увосень 2009 у касцёле расчыніў дзверы Музей царкоўнай спадчыны. \n\nНадмагільны помнік фундатару Льву Сапегу і двум ягоным жонкам месціцца справа ад галоўнага алтара. Таксама ў касцёле ёсць помнікі сыну і канцлера ВКЛ і іншым прадстаўнікам дынастыі. Прах Сапегаў спачывае ў крыпце пад алтаром."
    },
