      "by": "Адрас: Vilniaus, 10.\n\nУладальнікам віленскай бібліятэкі-чытальні \"Веды\" быў беларускі мецэнат Барыс Даніловіч. \n\nУ 1911 годзе бібліятэка \"Веды\" пераехала ў гэты будынак. Кампаньёнам Даніловіча стаў Іван Луцкевіч. З 1914 года ў гэтым доме жылі браты Луцкевічы і разам з кнігамі тут захоўваліся іх ўнікальныя старасвецкія калекцыі. Да 1918 года кватэра Луцкевічаў была цэнтрам беларускага адраджэнскага руху.\n\nБудынак быў цалкам перабудаваны ў 1960-я.",
      "ru": "Адрас: Vilniaus, 10.\n\nУладальнікам віленскай бібліятэкі-чытальні \"Веды\" быў беларускі мецэнат Барыс Даніловіч. \n\nУ 1911 годзе бібліятэка \"Веды\" пераехала ў гэты будынак. Кампаньёнам Даніловіча стаў Іван Луцкевіч. З 1914 года ў гэтым доме жылі браты Луцкевічы і разам з кнігамі тут захоўваліся іх ўнікальныя старасвецкія калекцыі. Да 1918 года кватэра Луцкевічаў была цэнтрам беларускага адраджэнскага руху.\n\nБудынак быў цалкам перабудаваны ў 1960-я.",
      "en": "Адрас: Vilniaus, 10.\n\nУладальнікам віленскай бібліятэкі-чытальні \"Веды\" быў беларускі мецэнат Барыс Даніловіч. \n\nУ 1911 годзе бібліятэка \"Веды\" пераехала ў гэты будынак. Кампаньёнам Даніловіча стаў Іван Луцкевіч. З 1914 года ў гэтым доме жылі браты Луцкевічы і разам з кнігамі тут захоўваліся іх ўнікальныя старасвецкія калекцыі. Да 1918 года кватэра Луцкевічаў была цэнтрам беларускага адраджэнскага руху.\n\nБудынак быў цалкам перабудаваны ў 1960-я."
