    "description": {
      "by": "Адрас: Vilniaus, 41.\n\nГэты пекны дом вядомы з 17 стагоддзя як галоўная віленская рэзідэнцыя роду Радзівілаў. На прыканцы 18 — першай палове 19 ст. барочна-рэнесансны палац таксама выконваў ролю тэатра.  \n\nУжо ў 20 ст. тут месцілася сціжма беларускіх установаў і арганізацыяў: Беларускі кааператыўны банк пад кіраўніцтвам праваслаўнага святара Аляксандра Каўша, Студэнцкі саюз, Беларускае кааператыўнае таварыства \"Пчала\", рэдакцыі дзіцячага часопіса \"Заранка\" і сельскагаспадарчага \"Саха\". \n\nУ другой палове 1920-х тут жыў ідэолаг беларускага адраджэння Антон Луцкевіч.\n\nСёння ў сценах былой віленскай рэзідэнцыі Радзівілаў працуе Літоўскі музей тэатру і кіно.",
      "ru": "Адрас: Vilniaus, 41.\n\nГэты пекны дом вядомы з 17 стагоддзя як галоўная віленская рэзідэнцыя роду Радзівілаў. На прыканцы 18 — першай палове 19 ст. барочна-рэнесансны палац таксама выконваў ролю тэатра.  \n\nУжо ў 20 ст. тут месцілася сціжма беларускіх установаў і арганізацыяў: Беларускі кааператыўны банк пад кіраўніцтвам праваслаўнага святара Аляксандра Каўша, Студэнцкі саюз, Беларускае кааператыўнае таварыства \"Пчала\", рэдакцыі дзіцячага часопіса \"Заранка\" і сельскагаспадарчага \"Саха\". \n\nУ другой палове 1920-х тут жыў ідэолаг беларускага адраджэння Антон Луцкевіч.\n\nСёння ў сценах былой віленскай рэзідэнцыі Радзівілаў працуе Літоўскі музей тэатру і кіно.",
      "en": "Адрас: Vilniaus, 41.\n\nГэты пекны дом вядомы з 17 стагоддзя як галоўная віленская рэзідэнцыя роду Радзівілаў. На прыканцы 18 — першай палове 19 ст. барочна-рэнесансны палац таксама выконваў ролю тэатра.  \n\nУжо ў 20 ст. тут месцілася сціжма беларускіх установаў і арганізацыяў: Беларускі кааператыўны банк пад кіраўніцтвам праваслаўнага святара Аляксандра Каўша, Студэнцкі саюз, Беларускае кааператыўнае таварыства \"Пчала\", рэдакцыі дзіцячага часопіса \"Заранка\" і сельскагаспадарчага \"Саха\". \n\nУ другой палове 1920-х тут жыў ідэолаг беларускага адраджэння Антон Луцкевіч.\n\nСёння ў сценах былой віленскай рэзідэнцыі Радзівілаў працуе Літоўскі музей тэатру і кіно."
    },
