    "id": "vilnia-palats-antoni-tyzenhawza",
    "title": {
      "by": "Палац Антоні Тызенгаўза",
      "ru": "Палац Антоні Тызенгаўза",
      "en": "Палац Антоні Тызенгаўза"
    },
    "category": "historical",
    "country": {
      "by": "Літва",
      "ru": "Литва",
      "en": "Lithuania"
    },
    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.68045,
      25.28257
    ],
    "description": {
      "by": "Адрас: Vokieciu, 28.\n\nУ другой палове XVIII ст. уладальнікам маёнтка быў магнат і асветнік Антоні Тызенгаўз. Мяркуецца, што аўтарам праекта палаца мог быць галоўны архітэктар ВКЛ Джузэпе дэ Сака. \n\nПасля банкруцтва Тызенгаўза, які кіраваў каралеўскімі эканоміямі на тэрыторыі Беларусі і Летувы, і ягонай смерці (1785), палац перайшоў да генеральшы фон Фітынгоф. Захаванае да сёння аблічча з манументальнымі класічнымі фасадамі і сіметрычнай кампазіцыяй будынак набыў у рэканструкцыю 1790 г. \n\nПадчас пажару ў 1944-м ад палаца захаваліся адны сцены. У 1945 узноўлены, а ў 1957 — рэканструяваны і рэстаўраваны.",
      "ru": "Адрас: Vokieciu, 28.\n\nУ другой палове XVIII ст. уладальнікам маёнтка быў магнат і асветнік Антоні Тызенгаўз. Мяркуецца, што аўтарам праекта палаца мог быць галоўны архітэктар ВКЛ Джузэпе дэ Сака. \n\nПасля банкруцтва Тызенгаўза, які кіраваў каралеўскімі эканоміямі на тэрыторыі Беларусі і Летувы, і ягонай смерці (1785), палац перайшоў да генеральшы фон Фітынгоф. Захаванае да сёння аблічча з манументальнымі класічнымі фасадамі і сіметрычнай кампазіцыяй будынак набыў у рэканструкцыю 1790 г. \n\nПадчас пажару ў 1944-м ад палаца захаваліся адны сцены. У 1945 узноўлены, а ў 1957 — рэканструяваны і рэстаўраваны.",
      "en": "Адрас: Vokieciu, 28.\n\nУ другой палове XVIII ст. уладальнікам маёнтка быў магнат і асветнік Антоні Тызенгаўз. Мяркуецца, што аўтарам праекта палаца мог быць галоўны архітэктар ВКЛ Джузэпе дэ Сака. \n\nПасля банкруцтва Тызенгаўза, які кіраваў каралеўскімі эканоміямі на тэрыторыі Беларусі і Летувы, і ягонай смерці (1785), палац перайшоў да генеральшы фон Фітынгоф. Захаванае да сёння аблічча з манументальнымі класічнымі фасадамі і сіметрычнай кампазіцыяй будынак набыў у рэканструкцыю 1790 г. \n\nПадчас пажару ў 1944-м ад палаца захаваліся адны сцены. У 1945 узноўлены, а ў 1957 — рэканструяваны і рэстаўраваны."
    },
