    "id": "vilnia-redaktsyya-adnowlenay-nashay-nivy-1991-96",
    "title": {
      "by": "Рэдакцыя адноўленай “Нашай Нівы” (1991-96)",
      "ru": "Рэдакцыя адноўленай “Нашай Нівы” (1991-96)",
      "en": "Рэдакцыя адноўленай “Нашай Нівы” (1991-96)"
    },
    "category": "historical",
    "country": {
      "by": "Літва",
      "ru": "Литва",
      "en": "Lithuania"
    },
    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.69064,
      25.28184
    ],
    "description": {
      "by": "Адрас: Žygimantų, 12.\n\n27 траўня 1991 года газета \"Наша Ніва\" адрадзілася ў Вільні, якая была ўжо сталіцай незалежнай Літвы. Сваім трэцім нараджэннем яна ўдзячная экс-рэдактару аддзела крытыкі часопіса \"Нёман\" Сяргею Дубаўцу. Мастацкім рэдактарам газеты стаў Сяргей Харэўскі, дзед якога яшчэ на пачатку XX стагоддзя быў адным з сямі падпісчыкаў «Нашай Нівы» у Новай Зеландыі. \n\nРэакцыя месцілася ў гэтым аднапавярховым будынку.",
      "ru": "Адрас: Žygimantų, 12.\n\n27 траўня 1991 года газета \"Наша Ніва\" адрадзілася ў Вільні, якая была ўжо сталіцай незалежнай Літвы. Сваім трэцім нараджэннем яна ўдзячная экс-рэдактару аддзела крытыкі часопіса \"Нёман\" Сяргею Дубаўцу. Мастацкім рэдактарам газеты стаў Сяргей Харэўскі, дзед якога яшчэ на пачатку XX стагоддзя быў адным з сямі падпісчыкаў «Нашай Нівы» у Новай Зеландыі. \n\nРэакцыя месцілася ў гэтым аднапавярховым будынку.",
      "en": "Адрас: Žygimantų, 12.\n\n27 траўня 1991 года газета \"Наша Ніва\" адрадзілася ў Вільні, якая была ўжо сталіцай незалежнай Літвы. Сваім трэцім нараджэннем яна ўдзячная экс-рэдактару аддзела крытыкі часопіса \"Нёман\" Сяргею Дубаўцу. Мастацкім рэдактарам газеты стаў Сяргей Харэўскі, дзед якога яшчэ на пачатку XX стагоддзя быў адным з сямі падпісчыкаў «Нашай Нівы» у Новай Зеландыі. \n\nРэакцыя месцілася ў гэтым аднапавярховым будынку."
    },
