    "description": {
      "by": "Адрас: Žvirgždyno, 3.\n\nНа віленскіх Бернардынскіх могілках, што на Зарэччы, мярод іншых пахаваны  адзін з першых даследчыкаў расліннага і жывёльнага свету Беларусі, прафесар батанікі і заалогіі Віленскага ўніверсітэта Станіслаў Баніфацы Юндзіл (1761-1847).",
      "ru": "Адрас: Žvirgždyno, 3.\n\nНа віленскіх Бернардынскіх могілках, што на Зарэччы, мярод іншых пахаваны  адзін з першых даследчыкаў расліннага і жывёльнага свету Беларусі, прафесар батанікі і заалогіі Віленскага ўніверсітэта Станіслаў Баніфацы Юндзіл (1761-1847).",
      "en": "Адрас: Žvirgždyno, 3.\n\nНа віленскіх Бернардынскіх могілках, што на Зарэччы, мярод іншых пахаваны  адзін з першых даследчыкаў расліннага і жывёльнага свету Беларусі, прафесар батанікі і заалогіі Віленскага ўніверсітэта Станіслаў Баніфацы Юндзіл (1761-1847)."
    },
