      "en": "Адрас: Aušros Vartu, 1.\n\nАд 1926 г. тут месцілася і кнігарня Беларускага выдавецкага таварыства. Тут прадаваліся беларускія кнігі, перыёдыкі, а таксама школьныя прылады для вучняў Віленскай беларускай гімназіі."
