    "title": {
      "by": "Дом-музей А.Міцкевіча",
      "ru": "Дом-музей А.Міцкевіча",
      "en": "Дом-музей А.Міцкевіча"
    },
    "category": "plaque",
    "country": {
      "by": "Літва",
      "ru": "Литва",
      "en": "Lithuania"
    },
    "city": {
      "by": "Вільня",
      "ru": "Вильнюс",
      "en": "Vilnius"
    },
    "coordinates": [
      54.68335,
      25.29183
    ],
    "description": {
      "by": "Адрас: Bernardinų, 11.\n\nЗаснаваны ў 1898 годзе да 100-годдзя паэта, музей размешчаны памяшканні, дзе Міцкевіч здымаў адзін з трох пакояў. Паэт жыў тут у 1822 годзе па вяртанні з Коўна і сканчаў паэму “Гражына”. \n\nПра гэта паспавядае мемарыяльная шыльда па-польску і па-літоўску, умацаваная ў панадворку будынка. \n\nМузей, які сёння належыць Вільнюскаму ўніверсітэту, змяшчае больш за 200 экспанатаў, сярод якіх, напрыклад, столік і крэсла, якімі Міцкевіч карыстаўся ў Парыжы, лісты да яго філаматаў, першыя прыжыццёвыя выданні — зборнік “Санеты” (1826) і “Конрад Валенрод” (1828).",
      "ru": "Адрас: Bernardinų, 11.\n\nЗаснаваны ў 1898 годзе да 100-годдзя паэта, музей размешчаны памяшканні, дзе Міцкевіч здымаў адзін з трох пакояў. Паэт жыў тут у 1822 годзе па вяртанні з Коўна і сканчаў паэму “Гражына”. \n\nПра гэта паспавядае мемарыяльная шыльда па-польску і па-літоўску, умацаваная ў панадворку будынка. \n\nМузей, які сёння належыць Вільнюскаму ўніверсітэту, змяшчае больш за 200 экспанатаў, сярод якіх, напрыклад, столік і крэсла, якімі Міцкевіч карыстаўся ў Парыжы, лісты да яго філаматаў, першыя прыжыццёвыя выданні — зборнік “Санеты” (1826) і “Конрад Валенрод” (1828).",
      "en": "Адрас: Bernardinų, 11.\n\nЗаснаваны ў 1898 годзе да 100-годдзя паэта, музей размешчаны памяшканні, дзе Міцкевіч здымаў адзін з трох пакояў. Паэт жыў тут у 1822 годзе па вяртанні з Коўна і сканчаў паэму “Гражына”. \n\nПра гэта паспавядае мемарыяльная шыльда па-польску і па-літоўску, умацаваная ў панадворку будынка. \n\nМузей, які сёння належыць Вільнюскаму ўніверсітэту, змяшчае больш за 200 экспанатаў, сярод якіх, напрыклад, столік і крэсла, якімі Міцкевіч карыстаўся ў Парыжы, лісты да яго філаматаў, першыя прыжыццёвыя выданні — зборнік “Санеты” (1826) і “Конрад Валенрод” (1828)."
    },
