    "description": {
      "by": "Адрас: Didžioji, 33 / Rūdninkų, 2.\n\nГазета \"Наша Доля\" была першым легальным перыядычным выданнем на беларускай мове, органам першай беларускай партыі Беларускай сацыялістычнай грамады. Чатыры нумары \"першай белорускай газэты для вёсковаго і местоваго рабочага народу\" выйшлі ў друкарні, якая месцілася ў гэтым будынку.",
      "ru": "Адрас: Didžioji, 33 / Rūdninkų, 2.\n\nГазета \"Наша Доля\" была першым легальным перыядычным выданнем на беларускай мове, органам першай беларускай партыі Беларускай сацыялістычнай грамады. Чатыры нумары \"першай белорускай газэты для вёсковаго і местоваго рабочага народу\" выйшлі ў друкарні, якая месцілася ў гэтым будынку.",
      "en": "Адрас: Didžioji, 33 / Rūdninkų, 2.\n\nГазета \"Наша Доля\" была першым легальным перыядычным выданнем на беларускай мове, органам першай беларускай партыі Беларускай сацыялістычнай грамады. Чатыры нумары \"першай белорускай газэты для вёсковаго і местоваго рабочага народу\" выйшлі ў друкарні, якая месцілася ў гэтым будынку."
    },
