      "en": "Адрас: Pylimo, 51/ Sodų, 1.\n\nНа пачатку 1907 г. \"першая беларуская газэта з рысункамі\" займала памяшканне ў гэтым доме на тагачаснай Завальнай. \n\nУжо доўгі час будынак, які знаходзіцца ў аварыйным стане, выстаўлены на продаж."
